/* sigaction_example.c: Demonstrate setting a custom signal handler for SIGUSR1 */
#define _POSIX_C_SOURCE 199309L
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>

// Custom signal handler function (three-argument style)
static void handler(int sig, siginfo_t *info, void *ucontext) {
    printf("\n[Handler] Caught signal %d (%s).\n", sig, (sig == SIGUSR1) ? "SIGUSR1" : "Unknown");
    printf("[Handler] Signal sent by process ID: %d (UID: %d)\n", info->si_pid, info->si_uid);
    // Exit cleanly after handling the signal
    _exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;

    // 1. Set flags to use the sa_sigaction handler (SA_SIGINFO)
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = handler;

    // 2. Clear the mask: no additional signals blocked while handling
    if (sigemptyset(&sa.sa_mask) == -1) {
        perror("sigemptyset");
        return EXIT_FAILURE;
    }

    // 3. Register the new action for SIGUSR1
    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    pid_t parent_pid = getpid();
    printf("PID %d: Waiting for SIGUSR1...\n", parent_pid);

    // Fork a child to send the signal to the parent after a delay
    if (fork() == 0) {
        sleep(1); 
        printf("[Child] Sending SIGUSR1 to parent (%d)...\n", parent_pid);
        if (kill(parent_pid, SIGUSR1) == -1) {
            perror("kill failed");
            exit(EXIT_FAILURE);
        }
        exit(EXIT_SUCCESS);
    }

    // Parent process waits for the signal indefinitely
    pause(); 

    // This point should not be reached if the signal handler executes
    return EXIT_SUCCESS; 
}
